import{_ as s,o as n,c as t,a3 as e}from"./chunks/framework.Dz5Q8p4s.js";const h=JSON.parse('{"title":"Trimming the Long-Tail of Visual World Modeling Evaluation","description":"","frontmatter":{"title":"Trimming the Long-Tail of Visual World Modeling Evaluation","arxiv":"2606.24256","date":"2026-06-23","authors":"Bingxuan Li, Yining Hong, Cheng Qian, Hyeonjeong Ha, Jiateng Liu, Zhenhailong Wang, Yue Guo, Yunzhu Li, Heng Ji","categories":"cs.CV","topics":"长尾物理交互, 世界模型评测, affordance 泛化","outline":[2,2]},"headers":[],"relativePath":"papers/2606.24256.md","filePath":"papers/2606.24256.md","lastUpdated":null}'),r={name:"papers/2606.24256.md"};function p(l,a,o,i,c,m){return n(),t("div",null,[...a[0]||(a[0]=[e('<h1 id="trimming-the-long-tail-of-visual-world-modeling-evaluation" tabindex="-1">Trimming the Long-Tail of Visual World Modeling Evaluation <a class="header-anchor" href="#trimming-the-long-tail-of-visual-world-modeling-evaluation" aria-label="Permalink to &quot;Trimming the Long-Tail of Visual World Modeling Evaluation&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2606.24256" target="_blank" rel="noreferrer">2606.24256</a></td></tr><tr><td><strong>提交日期</strong></td><td>2026-06-23</td></tr><tr><td><strong>作者</strong></td><td>Bingxuan Li, Yining Hong, Cheng Qian, Hyeonjeong Ha, Jiateng Liu, Zhenhailong Wang, Yue Guo, Yunzhu Li, Heng Ji</td></tr><tr><td><strong>分类</strong></td><td>cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>把同一个工具使用任务配上常规工具、属性相容的非常规替代品、以及属性冲突的不可能工具三档，再分预测式与描述式两种提示，测出生成模型在长尾物理交互上的系统性崩塌。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/physics-aware">物理感知视频生成</a></p></blockquote><div class="tip custom-block"><p class="custom-block-title">命名说明</p><p>arXiv abs 页的标题不含系统名，摘要里把基准称作 <strong>Tailor-Bench</strong>；v1 HTML 全文的标题与正文一律写作 <strong>TailOR</strong>。frontmatter 与一级标题按 abs 页标题，正文按全文用 TailOR。本站论文索引里的标题是「长尾问题（long tail）」、别名 Tailor-Bench，非编号错误。</p></div><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>真实世界的物理交互不是均匀分布的，而是长尾的。刀切面包、球砸碎玻璃、锤子钉钉子这类常见交互同时主导了人类经验与大规模视觉数据，构成分布的头部。头部之外是一条又长又杂的尾巴：不典型、临时凑合、依赖上下文，但物理上完全成立的交互。作者给的两个例子很好——硬币的刚性边缘若能传递足够扭矩，就可以当一字螺丝刀用；一本厚精装书可以当锤子砸开核桃。单看每一种都罕见，合起来却占据了可能物理交互空间的很大一部分。</p><p>问题在于当前评测全在头部。作者引了一个刺眼的对照：在 MMGR 数据集上，Sora-2 的物理准确率 86%、视觉真实感 92%，看上去已经很会模拟物理交互了。但<strong>头部上的成功与真正掌握物理原理在观测上是无法区分的</strong>，因为常见场景可以靠模式识别与共现匹配达成。长尾场景考察的是一种根本不同的能力：不是回忆高频物理模式，而是推理一次交互<strong>为什么</strong>能成立。</p><p>于是核心问题被提得很干脆：世界模型是内化并泛化了物理原理，还是主要依赖训练数据里的统计规律？</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>图像生成评测侧，T2I-CompBench、GenEval、GenAI-Bench 关注组合性、物体级正确性与 prompt 对齐，TIFA 引入基于问答的可解释忠实度评估，GECKO 进一步指出评测设计本身的困难（prompt 敏感性、自动指标与人类判断的局限）。视频侧，VideoPhy 与 VideoPhy-2 评物理常识，PhyWorldBench 与 Morpheus 用结构化场景和真实物理实验检验物理真实感，VBench-2.0、Video-Bench、UI2V-Bench 分别面向内在忠实度、人类对齐与基于理解的生成质量。</p><p>作者对这一整片工作的批评是精确的：它们<strong>事先固定了评价标准并统一施加</strong>，重心落在感知质量、prompt 忠实度、或者常规场景下的物理正确性。缺口不是「没人测物理」，而是没人测<strong>非常规但物理上仍然成立</strong>的那一类——这类场景要求模型基于物体属性泛化 affordance，而不是复用记住的工具-任务关联。这个缺口之所以此前没被填上，一个直接的原因是这类数据无法从自然分布里采集（它们本来就罕见），必须被构造出来。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>先前已知的事实是：生成模型在常见工具-任务对上表现优异，且这种优异可以完全由共现统计解释。要把「记住模板」与「理解原理」分开，需要一个能让两者做出不同预测的设定。</p><p>分离设计几乎是唯一自然的：保持任务不变，只换工具。如果模型理解的是<strong>属性</strong>（刚性、锐利、杠杆、力的方向），那么换成一个属性相容但不常见的工具，它应该照样成功；如果模型记住的是<strong>工具-任务对</strong>，它会失败。这给出了 Unconventional 一档。</p><p>但只有这一档还不够，因为一个「什么工具都说能用」的模型也会在这一档拿高分。所以必须补一个反向档：给一个属性上明确冲突的工具，正确行为是生成失败。这给出了 Impossible 一档，它检验的是约束意识而非泛化能力。三档合起来才能把「盲目泛化」与「真正理解」分开。</p><p>第二个分离维度来自另一个观察：一个模型可能推不出结果，也可能推得出但画不出来。把结果藏起来让它自己推（Predictive），与把结果直接告诉它让它照做（Descriptive），恰好把「推理失败」与「实现失败」拆开。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>把工具换掉，任务不变。理解物理属性的模型换成硬币照样能拧螺丝，记住共现模板的模型只会画出硬币旁边躺着一颗没拧进去的螺丝。再补一档属性冲突的工具，逼出另一半答案——真正懂约束的模型会画出失败，而不是把海绵当刀用把胡萝卜切开。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>每个评测实例形式化为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">x</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathcal">A</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathcal" style="margin-right:0.0993em;">U</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathcal" style="margin-right:0.0738em;">I</span><span class="mclose">)</span></span></span></span>：任务目标 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span></span></span></span>（如「撑住门」「堵住水槽」）、常规工具 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span></span></span></span>、所需功能属性集 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal">A</span></span></span></span>、属性相容的非常规替代集 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal" style="margin-right:0.0993em;">U</span></span></span></span>、属性冲突的不可能工具集 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal" style="margin-right:0.0738em;">I</span></span></span></span>。</p><p><strong>数据来源。</strong> 动作本体来自 HICO-DET 的人-物交互动词类，人工核验筛出 18 个动作，每个动作配上动作名、动作描述、底层物理与核心 affordance 需求。物体-属性图来自 ConceptNet（如 key HasProperty sharp），在生成非常规与不可能工具时提供候选物体的附加信息。</p><p><strong>七步构造（LLM 用 GPT-5）。</strong> 步骤一由动作生成具体任务，含 task_goal、expected_outcome、original_tool、required_tool_attributes。步骤二针对所需属性提出不常见但可行的替代工具。步骤三先生成相反 affordance（sharp 对 blunt/round、long 对 short），再查物体-属性图找出满足这些矛盾属性的物体，并生成它们被用于该任务时的预期失败结果。步骤四人工审核，每个任务保留两个非常规工具与两个不可能工具，要求非常规替代物理上确实可行、负样本的不可能性明确无歧义、且视觉上可清晰呈现。步骤五生成两类 prompt。步骤六生成 checklist 式评测 rubric。步骤七第二轮人工核验。人工环节共四名志愿者，三名计算机硕士生 + 一名物理本科生。</p><p><strong>规模。</strong> 80 个工具使用任务，每个任务 5 个工具变体（1 常规 + 2 非常规 + 2 不可能）= 400 个评测任务；每个任务-工具对配 4 个 prompt（预测式/描述式 × 图像/视频）= 1600 条 prompt。按场景分：Regular 80 任务 / 320 prompt，Unconventional 与 Impossible 各 160 任务 / 640 prompt。</p><p><strong>一个完整例子。</strong> 任务目标「拧紧一字螺丝」，常规工具螺丝刀，所需属性「刚性、扁薄边缘、可传递扭矩」。非常规工具「硬币」——满足全部属性。不可能工具「海绵」——违反刚性。描述式图像 prompt 写成「生成一张图像：用一枚硬币拧紧一字螺丝，螺丝完全拧入木质表面」。预测式 prompt 则只问「用硬币去拧一字螺丝会发生什么」，把结果藏起来。视频的描述式 prompt 还要额外描述关键交互动力学以约束时序连贯。</p><p><strong>评测。</strong> 四个维度：Instruction Adherence（0–100%，由实体完整性、属性保真、场景合理性三项 checklist 子分的算术平均构成）、Interaction Accuracy（0–100%，由状态变化正确性、affordance 落地、运动合理性构成，最后一项仅用于视频）、Physical Realism（0–5 开放评分）、Perceptual Quality（0–5，视频还额外考察跨帧身份一致性）。自动评测用 gemini-2.5-pro 当 judge，对主观维度要求先推理再给分；人工评测招募 9 名标注者（4 名博士生、3 名本科生、2 名硕士生），每个样本至少 3 人独立评。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文的形式化止于实例定义与指标的分解式聚合，没有推导。评测实例 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">x</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathcal">A</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathcal" style="margin-right:0.0993em;">U</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathcal" style="margin-right:0.0738em;">I</span><span class="mclose">)</span></span></span></span> 的三档由属性关系确定：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5782em;vertical-align:-0.0391em;"></span><span class="mord mathnormal">u</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal" style="margin-right:0.0993em;">U</span></span></span></span> 满足 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal">A</span></span></span></span> 中全部所需属性，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6986em;vertical-align:-0.0391em;"></span><span class="mord mathnormal">i</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal" style="margin-right:0.0738em;">I</span></span></span></span> 违反 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal">A</span></span></span></span> 中至少一个关键属性。Instruction Adherence 与 Interaction Accuracy 都是 checklist 通过率的算术平均，Physical Realism 与 Perceptual Quality 是 0–5 的开放评分。四个维度不做加权合成，全文按维度分别报告，这一点其实是好设计——避免了把可诊断的分解压成一个不可诊断的总分。除此之外，本文无形式化数学推导。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p>评测对象：图像模型 Z-Image、Qwen-Image、GPT-Image-1、Nano-Banana-2；视频模型 HunyuanVideo-1.5、Wan-2.2、Sora-2、Veo-3.1。表 2 以「自动 / 人工」成对报告。</p><p><strong>结论一：长尾断崖普遍存在。</strong> 所有模型在所有四个维度上都随 Regular → Unconventional → Impossible 单调下降。以最强的图像模型 Nano-Banana-2 的预测式设定为例，Instruction Adherence 自动分 69% → 46% → 42%，Interaction Accuracy 65% → 43% → 38%，Physical Realism 3.6 → 2.8 → 2.6。最强的视频模型 Sora-2：66% → 44% → 39%，63% → 40% → 36%，3.1 → 2.3 → 2.2。下降在 Interaction Accuracy 与 Physical Realism 上最陡，而 Perceptual Quality 下降相对温和，作者据此论证失败源于 affordance 层面的理解不足而非感知质量。</p><p><strong>结论二：视频模型比图像模型更脆弱。</strong> 所有指标上视频模型都低于图像模型。作者的解释是前向物理仿真的额外难度——不仅要画出一个合理的静态交互，还要跨帧维持时序连贯的状态转移；早期帧的小错误会传播放大成级联失败。</p><p><strong>结论三：给了答案也不照做。</strong> 敏感性分析显示，多数模型（尤其视频模型）的描述式表现<strong>不高于甚至低于</strong>预测式，且两者差距在 Unconventional 一档最大。作者读作：当被明确要求产出某个特定结果时，模型仍然退回训练数据里的熟悉模式。子指标拆解进一步显示，描述式对图像模型有帮助（主要体现在实体完整性与场景合理性），对视频模型帮助小得多，视频模型的属性保真度即使在描述式下依然偏低。</p><p><strong>结论四：自动与人工评测排名基本一致</strong>，两套协议都把 Sora-2 认作最好的视频模型、Nano-Banana-2 认作最好的图像模型。</p><p><strong>失败模式分析（图像）：</strong> Regular 档的失败由结果不正确与属性不准确共同主导，其次是物理违反（锤子位置正确但钉子没被钉进去，同时锤子略微形变或尺度不对，接触时物体甚至互相穿插）。Unconventional 档由结果不正确主导，其次是 affordance 误泛化（模型认出书是刚性的，却不用平面施力）。Impossible 档由<strong>指令遵循失败</strong>主导——模型直接忽略约束，例如画出海绵在切胡萝卜，隐式地把海绵当成了刚体。</p><p><strong>失败模式分析（视频）：</strong> Regular 档由不合理动力学主导（锤子没有可见的挥动就已接触钉子、反复敲击却钉不进、跨帧抖动）。Unconventional 档由 affordance 误泛化主导（书一开始像敲击工具，运动过程中却表现得像软物）。Impossible 档由时序不一致主导（核桃在没有任何可见力累积的情况下突然裂开，而软工具与它接触时自身不形变）。</p><div class="warning custom-block"><p class="custom-block-title">需要注意的数据问题</p><p>以下几点论文未讨论，但直接影响结论的读法。</p><ol><li><strong>人工分只覆盖 80 条 prompt / 1080 个生成样本</strong>（附录 B.1），而自动分覆盖全部 1600 条。表 2 把两者并排呈现，正文的「强一致」结论建立在这个不等规模的对照上。</li><li><strong>弱模型上自动分与人工分差距大且会翻转排名。</strong> 例如预测式 Impossible 的 Interaction Accuracy，自动分 HunyuanVideo 22% &gt; Wan-2.2 17%，人工分却是 HunyuanVideo 20% &lt; Wan-2.2 30%；预测式 Unconventional 上 HunyuanVideo 自动 23% vs 人工 34%。</li><li><strong>多处 Interaction Accuracy 高于 Instruction Adherence</strong>，与「先把东西放对、再谈交互对不对」的层级设定相反。如预测式 Impossible 的 HunyuanVideo（IA 18% / IntAcc 22%）、预测式 Regular 的 Wan-2.2（44% / 49%）、描述式 Impossible 的 Z-Image（21% / 24%）。</li><li><strong>Sora-2 与 Veo3 有部分 prompt 被安全过滤拦截</strong>，作者用从全集另采的 prompt 替换，因此这两个模型与其余模型并非在完全相同的 prompt 集上比较。</li></ol></div><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：物理交互是长尾的，而现有评测全在头部，头部上的高分可以完全由共现统计解释。TailOR 的做法是固定任务只换工具，用「常规 / 属性相容的非常规 / 属性冲突的不可能」三档把「记模板」与「懂属性」分开，再用预测式与描述式两种提示把「推不出结果」与「推得出但画不出」分开。80 个任务 × 5 个工具变体 × 4 类 prompt = 1600 条评测实例，动作本体取自 HICO-DET，属性图取自 ConceptNet，构造用 GPT-5，两轮人工核验，评测用 gemini-2.5-pro 加 9 人标注。结果是一致的单调下降：所有模型从 Regular 到 Unconventional 再到 Impossible 全线滑坡，跌幅集中在交互准确性与物理真实感而非感知质量，视频模型比图像模型更脆弱。最刺眼的发现是描述式并不比预测式好——即使把正确结果直接写进 prompt，模型仍然退回熟悉的交互模板。</p><p><strong>3 句话版</strong>：固定任务、只换工具，用属性相容与属性冲突两个方向的替换把物理理解从共现记忆里剥离出来。八个前沿图像与视频模型在长尾档上全线崩塌，跌幅集中在 affordance 层面而非画质。给出正确答案也救不回来，说明问题不只在推理，也在物理落地的生成过程本身。</p><p><strong>1 句话版</strong>：把锤子换成书，模型就露馅了。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的是：<strong>GPT-5 生成、四名志愿者核验的「非常规工具确实可行、不可能工具确实不可行」这一标注是可靠的。</strong> 整个长尾断崖的解释力全押在这上面。如果相当一部分 Unconventional 实例其实是边缘情形——硬币能拧的只是低扭矩的一字螺丝，精装书能砸开的只是薄壳核桃且要看施力方式——那么一个生成「没拧动 / 没砸开」的模型可能是对的，却被 rubric 判为失败。此时 Regular → Unconventional 的落差里混进了「模型与 GPT-5 的物理直觉不一致」这一成分，而它与「模型不会 affordance 泛化」在数据里无法区分。</p><p>有几条线索让这个担心具体化。论文自己给的 Unconventional 失败例就是这种情形：「用书当锤子钉钉子，书被放在钉子旁边但没能把钉子钉进去」——这在现实里是否算失败，取决于书的重量、钉子的长度、木头的硬度，rubric 却按二值 checklist 判定。核验团队里只有一名物理背景成员，其余为计算机专业。标注者一致性 Krippendorff&#39;s <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.72</span></span></span></span>、开放评分的两两 Spearman 0.68 属于「实质性一致」但不高，说明连人类之间对这些实例的判断也存在可观分歧。</p><p>若这个假设不成立，塌掉的是「长尾断崖幅度」这一定量结论以及由它推出的「模型只会模板插值」这一因果解释。不塌的是 Impossible 一档的定性发现——海绵切胡萝卜、核桃无力自裂这类例子无论标注多宽松都是明确的约束违反，而它恰恰是失败模式分析里最干净的部分。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做，且直接检验 §9：</p><ul><li>从 TailOR 的 Unconventional 档随机抽 30 个任务-工具对（例如硬币拧螺丝、书砸核桃、回形针替代拉链头）。</li><li>招 5 名有动手经验的被试（非本论文标注者），只给 task_goal、工具名与所需属性，不给 expected_outcome，让他们独立判断「这个工具能否完成任务」，并给出 0–100 的把握度。</li><li>同时，对其中 10 个实例<strong>实际动手做一遍</strong>并拍照，作为地面真值。</li><li>判定标准：若 5 人判断的多数意见与 GPT-5 标注的一致率低于 80%，或平均把握度低于 70，说明这批实例的可行性本身存在争议，长尾断崖里包含标注噪声成分；若一致率超过 90% 且实拍验证全部支持标注，则假设成立，断崖可以按论文的解释读。</li></ul><p>再加一个几乎免费的对照：把那 10 张实拍照片喂给 gemini-2.5-pro judge，按同一套 rubric 打分。如果<strong>真实照片</strong>的 Interaction Accuracy 也只有 60–70%，那么瓶颈有相当一部分在 judge 而非被评模型，表 2 的绝对数值需要按这个上限重新解读。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>最有力的攻击是给「长尾断崖」一个更廉价的替代解释：<strong>它测的可能是文本到图像的组合绑定能力，而不是物理推理能力。</strong></p><p>论证如下。Unconventional prompt 必然包含罕见的物体对（「硬币 + 一字螺丝」「书 + 钉子」），这类组合在文本-图像配对的训练分布里同样罕见。T2I-CompBench 一系工作已经反复记录了生成模型在罕见属性绑定与罕见物体组合上的系统性失败，而那与物理推理无关。论文自己的子指标拆解正好为这个解释提供了弹药：视频模型即使拿到描述式 prompt，<strong>属性保真度依然偏低</strong>——属性保真度衡量的是「工具是否呈现出所需的功能属性」，它更像一个绑定问题而非物理问题。</p><p><strong>具体反例实验</strong>：构造一个「非物理组合」对照集。保持完全相同的罕见物体对，但把任务目标换成不涉及任何物理交互的静态构图，例如「生成一张图像：一枚硬币静静地放在一颗一字螺丝旁边的木桌上」「一本精装书和一颗核桃并排摆在桌上」。跑同样的八个模型，用只含实体完整性与属性保真度的简化 rubric 评分。</p><ul><li>若这个对照集上的 Instruction Adherence 与 Unconventional 档相当（例如都在 45% 上下），那么长尾断崖的主要成分是罕见组合的绑定失败，物理推理的解释被大幅削弱。</li><li>若对照集上分数显著更高（例如 75%+），说明模型能画出这两个物体共存的场景、只是不能让它们正确交互，物理推理的解释成立。</li></ul><p>这个实验成本极低（只需要重新生成一批 prompt 并复用 judge），却能把论文最核心的因果归因一分为二。论文没有做任何这类非物理对照，因此目前它无法排除组合性解释。</p><p>另一个补充攻击针对 Impossible 一档的可打分性：一个什么都生成不出来的模型（输出模糊、结构崩坏）与一个正确理解「海绵切不动胡萝卜」的模型，在 Interaction Accuracy 上可能拿到相近的分数，因为两者都没有呈现「胡萝卜被切开」。要区分它们，rubric 必须包含「是否明确呈现了失败」这一正向项，而当前的 checklist 描述里只写到「failure depiction in impossible cases」，未说明是否对「什么也没发生」与「明确呈现失败」区别对待。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动它的局限</strong>：TailOR 只能诊断，不能干预。它告诉我们模型把「锤子-钉子」记成了整体视觉模板，却没有给出让模型改学「刚性 + 质量 + 挥动」这些可迁移物理原语的路径。而且它的三档划分是离散的——常规、非常规、不可能——现实中的可行性是连续的（硬币能拧多大扭矩的螺丝，取决于硬币厚度与螺丝槽宽度）。</p><p><strong>新的 framing</strong>：把长尾评测从<strong>离散三分类</strong>改造成<strong>沿属性轴的连续可行性边界回归</strong>。对每个任务，不再只问「这个工具行不行」，而是沿一条物理属性轴（如工具的弯曲刚度，从钢尺到塑料尺到硬纸板到海绵）连续采样一串工具，要求模型对每一个都给出结果。真正理解物理的模型，其成功/失败的翻转应该发生在与真实临界值一致的位置上；只会模板匹配的模型要么处处成功、要么在与物理无关的位置翻转。这把「模型懂不懂」从一个二值判断变成了一条可以与真实临界值逐点比对的曲线，判别力远高于三档划分。</p><p><strong>可借鉴的相邻工具</strong>：心理物理学的阈值估计方法（阶梯法、psychometric function 拟合）提供了用少量试次高效定位翻转点的成熟范式；直觉物理学的经典工作（Physion 一系）提供了可以在仿真里精确控制材料参数以确定真实临界值的手段；主动学习里的不确定性采样可以把采样点集中在预测翻转点附近，把每个任务的生成成本从「一串工具」压到几次。</p><p><strong>第一个实验</strong>：选 10 个 TailOR 任务，每个沿一条属性轴取 8 个工具，用仿真器或简单实测确定真实翻转点。让 Nano-Banana-2 与 Sora-2 在预测式设定下生成全部 80 个实例，拟合各自的 psychometric function，报告两个量——翻转点相对真实临界值的偏移，以及曲线的陡峭度。可预测的结果是：模型的曲线远比真实的平缓（说明它对属性变化不敏感），且翻转点系统性偏向「常规工具成功、其余全失败」的位置。若如此，就得到了一个比「三档单调下降」精确得多的失败刻画，也直接给出了后续训练该往哪个方向加监督。</p>',60)])])}const d=s(r,[["render",p]]);export{h as __pageData,d as default};
